export default function (pi) {
  let dumps = 0;
  pi.registerTool({
    name: "dump", label: "Dump", description: "Oversized local output",
    parameters: { type: "object", properties: {} },
    async execute() {
      const sizes = [600000];
      const chars = sizes[Math.min(dumps++, sizes.length - 1)];
      return { content: [{ type: "text", text: `DUMP_HEAD ${"x".repeat(chars)} DUMP_TAIL` }, ...[]], details: {}, terminate: false };
    },
  });
}

export default function (pi) {
  const image = { type: "image", mimeType: "image/png", data: "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a0ioAAAAASUVORK5CYII=" };
  const replacement = (kind) => [{ type: "text", text: `${kind}_START ${"r".repeat(15000)} ${kind}_END` }, image];
  pi.on("turn_end", (event) => {
    if (!event.toolResults.some((entry) => entry.toolName === "dump")) return;
    const toolId = event.toolResultEntryIds[0];
    return {
      entries: [
        ...event.entries,
        { type: "context_edit", targetId: "5eed0001", replacement: { content: replacement("OWNER") } },
        { type: "context_edit", targetId: toolId, replacement: { content: replacement("TOOL") } },
        { type: "custom_message", customType: "review-draft", display: true, content: replacement("CUSTOM") },
        { type: "custom_message", customType: "context-pressure", display: false, content: "p".repeat(600000) },
      ],
    };
  });
}
